// src/trigger/send-welcome-email.ts
import { task, logger } from '@trigger.dev/sdk/v3';
import { sendEmail } from '../lib/email';

export const sendWelcomeEmail = task({
  id: 'send-welcome-email',
  run: async (payload: { userId: string; email: string }) => {
    logger.log('Sending welcome email', { userId: payload.userId });

    await sendEmail({
      to: payload.email,
      subject: 'Welcome!',
      html: '<h1>Welcome aboard</h1>',
    });

    return { success: true };
  },
});

// In your API route:
import { sendWelcomeEmail } from '../trigger/send-welcome-email';

// Fire-and-forget: returns a handle immediately
const handle = await sendWelcomeEmail.trigger({
  userId: 'user_123',
  email: 'jane@example.com',
});

console.log('Triggered run:', handle.id);

import { task, logger, wait } from '@trigger.dev/sdk/v3';
import { fetchExternalData, processData } from '../lib/data';

export const processUserData = task({
  id: 'process-user-data',
  retry: {
    maxAttempts: 5,
    factor: 2,
    minTimeoutInMs: 1_000,
    maxTimeoutInMs: 30_000,
  },
  run: async (payload: { userId: string }) => {
    logger.log('Processing user data', { userId: payload.userId });

    const raw = await fetchExternalData(payload.userId);

    // Pause the run for 30 seconds (does not block a worker thread)
    await wait.for({ seconds: 30 });

    const result = await processData(raw);

    logger.log('Processing complete', { result });
    return result;
  },
});
